try:
 fd=os.open(p,os.O_WRONLY); os.close(fd); result[\"open\"]=\"SUCCEEDED\"
except OSError as e:
 result.update(open=\"DENIED\",errno=e.errno,error=str(e))
mounts=[]
for line in open(\"/proc/self/mountinfo\"):
 fields=line.split(); m=fields[4];
 if p==m or p.startswith(m.rstrip(\"/\")+\"/\"): mounts.append((len(m),line.strip()))
result[\"covering_mount\"]=max(mounts)[1] if mounts else None; result[\"sha256_after\"]=h(); result[\"unchanged\"]=before==result[\"sha256_after\"]; print(json.dumps(result)); print(\"ROOT_PROTOCOL\"); print(open(\"/home/tcuni-claw/.codex/astra-planner.md\").read())'"

